/**
 * Shared sync object names used across CLI and future app clients.
 * @typedef {"articles"|"blogs"|"collections"|"media"|"menus"|"metafields"|"metaobjects"|"pages"|"products"|"selling plans"|"themes"} SyncObjectType
 */

/**
 * @typedef {"create-and-update"|"create"|"update"} SyncMode
 */

/**
 * @typedef {"continue"|"fail"} ExportFailureBehavior
 */

/**
 * @typedef {"queued"|"running"|"completed"|"failed"} RunStatus
 */

/**
 * @typedef {"sync"|"import"} RunType
 */

/**
 * @typedef {Object} StoreCredentials
 * @property {string} [id]
 * @property {string} [name]
 * @property {string} [store_name]
 * @property {string} [shop]
 * @property {string} [accessToken]
 * @property {boolean} [isTestStore]
 * @property {string|null} [testStoreNotes]
 */

/**
 * @typedef {Object} SyncConfig
 * @property {SyncObjectType[]} objects
 * @property {StoreCredentials|string|null} [source]
 * @property {StoreCredentials|string|null} [destination]
 * @property {boolean} [createOnly]
 * @property {boolean} [updateOnly]
 * @property {SyncMode} [syncMode]
 * @property {boolean} [cleanDestination]
 * @property {boolean} [exportBeforeSync]
 * @property {string} [outputPath]
 * @property {ExportFailureBehavior} [exportFailureBehavior]
 * @property {"dependencies"|"full"} [themeSyncMode]
 * @property {string|null} [destinationThemeId]
 * @property {"clear"|"keep"|"error"} [missingTemplatePolicy]
 * @property {string|string[]} [sourceProductIds]
 * @property {(string|null)[]|string} [destinationProductIds]
 * @property {boolean} [verbose]
 */

/**
 * @typedef {Object} SyncValidationError
 * @property {string} code
 * @property {string} message
 * @property {string} [field]
 * @property {Record<string, unknown>} [meta]
 */

/**
 * @typedef {Object} SyncObjectResult
 * @property {SyncObjectType} objectType
 * @property {"success"|"failed"|"skipped"} status Success means the object executor completed without fatal object errors; failed means the object executor threw or returned errors; skipped means the object was intentionally not executed, including unsupported placeholder objects.
 * @property {number} [created]
 * @property {number} [updated]
 * @property {number} [deleted]
 * @property {string[]} [warnings]
 * @property {string[]} [errors]
 * @property {Record<string, unknown>} [summary] May include `unsupported: true` for placeholder object types that are recognized but not implemented.
 */

/**
 * @typedef {Object} SyncRunResult
 * @property {boolean} success False for validation failure, fatal preflight failure, or any failed object result. Unsupported/skipped objects alone do not make the run fail.
 * @property {SyncConfig|null} config
 * @property {SyncObjectType[]} orderedObjects
 * @property {SyncObjectResult[]} objectResults
 * @property {string[]} warnings
 * @property {string[]} errors
 * @property {SyncValidationError[]} [validationErrors]
 */

/**
 * @typedef {Object} ExportObjectResult
 * @property {string} objectType
 * @property {"success"|"failed"|"skipped"} status
 * @property {string|null} [filepath]
 * @property {number} count
 * @property {number} [downloaded]
 * @property {number} [failed]
 * @property {string[]} [warnings]
 * @property {string[]} [errors]
 */

/**
 * @typedef {Object} ExportRunResult
 * @property {boolean} success
 * @property {ExportObjectResult[]} results
 * @property {string[]} warnings
 * @property {string[]} errors
 */

/**
 * @typedef {Object} ImportObjectResult
 * @property {string|null} objectType
 * @property {"success"|"failed"|"skipped"} status
 * @property {number} [created]
 * @property {number} [updated]
 * @property {number} [skipped]
 * @property {number} [errors]
 * @property {string} [filepath]
 * @property {boolean} [dryRun]
 * @property {string} [error]
 */

/**
 * @typedef {Object} ImportRunResult
 * @property {boolean} success
 * @property {ImportObjectResult[]} results
 * @property {string[]} warnings
 * @property {string[]} errors
 */

/**
 * @typedef {Object} SyncReporter
 * @property {(message: string, meta?: Record<string, unknown>) => void} [info]
 * @property {(message: string, meta?: Record<string, unknown>) => void} [warn]
 * @property {(message: string, meta?: Record<string, unknown>) => void} [error]
 * @property {(objectType: SyncObjectType, meta?: Record<string, unknown>) => void} [objectStarted]
 * @property {(objectType: SyncObjectType, summary?: Record<string, unknown>) => void} [objectFinished] Called exactly once for each attempted object with at least `status`; may include counters, warnings, errors, and summary metadata.
 */

/**
 * @typedef {Object} SyncRunSummary
 * @property {string} runId
 * @property {RunType} runType
 * @property {RunStatus} status
 * @property {string|null} [syncConfigId]
 * @property {string|null} [sourceStoreName]
 * @property {string|null} [sourceStoreShop]
 * @property {string|null} [destinationStoreName]
 * @property {string|null} [destinationStoreShop]
 * @property {string[]} objects
 * @property {SyncMode|null} [syncMode]
 * @property {boolean} [cleanDestination]
 * @property {boolean} [exportBeforeSync]
 * @property {string|null} [exportPath]
 * @property {ExportFailureBehavior|null} [exportFailureBehavior]
 * @property {number|string|Date} requestedAt
 * @property {number|string|Date|null} [startedAt]
 * @property {number|string|Date|null} [completedAt]
 * @property {SyncRunResult|ImportRunResult|null} [result]
 * @property {string|null} [errorMessage]
 */

/**
 * @typedef {Object} SyncRunEvent
 * @property {string} id
 * @property {string} runId
 * @property {string} eventName
 * @property {Record<string, unknown>|null} payload
 * @property {number|string|Date} createdAt
 */

/**
 * @typedef {Object} SyncRunRecord
 * @property {SyncRunSummary} summary
 * @property {SyncRunEvent[]} events
 */

const SYNC_OBJECT_TYPES = Object.freeze([
  'articles',
  'blogs',
  'collections',
  'media',
  'menus',
  'metafields',
  'metaobjects',
  'pages',
  'products',
  'selling plans',
  'themes'
]);

const SYNC_MODES = Object.freeze([
  'create-and-update',
  'create',
  'update'
]);

const EXPORT_FAILURE_BEHAVIORS = Object.freeze([
  'continue',
  'fail'
]);

const THEME_SYNC_MODES = Object.freeze([
  'dependencies',
  'full'
]);

const MISSING_TEMPLATE_POLICIES = Object.freeze([
  'clear',
  'keep',
  'error'
]);

const RUN_STATUSES = Object.freeze([
  'queued',
  'running',
  'completed',
  'failed'
]);

const RUN_TYPES = Object.freeze([
  'sync',
  'import'
]);

const SHOPIFY_ADMIN_API_VERSION = '2026-01';

const exported = {
  SYNC_OBJECT_TYPES,
  SYNC_MODES,
  EXPORT_FAILURE_BEHAVIORS,
  THEME_SYNC_MODES,
  MISSING_TEMPLATE_POLICIES,
  RUN_STATUSES,
  RUN_TYPES,
  SHOPIFY_ADMIN_API_VERSION
};

module.exports = exported;
module.exports.default = exported;
